import {RULES} from './learning-model.js?v=20261102-learning2';
export const METHOD_REVIEWED='2026-11-02';
export const METHOD_SOURCES=[
 ['Yang et al. (2021)','Testing (quizzing) boosts classroom learning: A systematic and meta-analytic review','https://pubmed.ncbi.nlm.nih.gov/33683913/','Aktives Abrufen unterstützt das Behalten; die Wirkung hängt unter anderem von Aufgabe, Feedback und Prüfung ab.','Retrieval practice supports retention; effects depend on tasks, feedback and assessment.'],
 ['Latimier, Peyre & Ramus (2021)','A Meta-Analytic Review of the Benefit of Spacing out Retrieval Practice Episodes on Retention','https://doi.org/10.1007/s10648-020-09572-8','Verteiltes Abrufen ist besser belegt als eine bestimmte Folge von Intervallen.','Evidence supports spaced retrieval, not one particular interval sequence.'],
 ['Rawson & Dunlosky (2022)','Successive Relearning: An Underexplored but Potent Technique for Obtaining and Maintaining Knowledge','https://doi.org/10.1177/09637214221100484','Erfolgreiches Erinnern in getrennten Sitzungen unterscheidet sich vom kurzfristigen Wiederholen.','Successful retrieval across spaced sessions differs from short-term repetition.'],
 ['Butler & Roediger (2008)','Feedback enhances the positive effects and reduces the negative effects of multiple-choice testing','https://pubmed.ncbi.nlm.nih.gov/18491500/','Korrekturfeedback hilft auch, falsche Auswahlantworten nicht mitzulernen.','Corrective feedback also helps prevent learning incorrect distractors.'],
 ['van den Broek et al. (2023)','Optimizing Multiple-Choice Questions for Retrieval Practice: Delayed Display of Answer Alternatives Enhances Vocabulary Learning','https://doi.org/10.1037/edu0000810','Zunächst verborgene Optionen unterstützten das Vokabellernen unter den untersuchten Bedingungen.','Initially hidden options supported vocabulary learning under the conditions studied.'],
 ['Brom et al. (2026)',"Retrieval Practice in the Wild: Comparing Different Multiple-Choice Question Formats on a Children's TV Gaming Site",'https://doi.org/10.1002/acp.70217','Selbstbestimmtes Einblenden zeigte kleine Vorteile bei der Ausdauer, aber keinen Unterschied im gemessenen kurzfristigen Lernzuwachs.','Learner-paced revealing showed small benefits for persistence, but no difference in measured short-term learning gains.'],
 ['Ruitenburg et al. (2026)','A Meta-Analysis of the Effectiveness and Boundary Conditions of Retrieval Practice, Distributed Practice, and Interleaved Practice in Authentic School Classrooms','https://doi.org/10.1007/s10648-026-10225-5','Die Wirkung dieser Lernprinzipien hängt vom Lernmaterial und Unterrichtskontext ab.','Effects of these learning principles depend on material and classroom context.']
];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderLearningMethod(english=false){
 const c=(de,en)=>english?en:de,ref=n=>` <a href="#lernmethode/method-source-${n+1}">[${n+1}]<span class="sr"> ${c('Quelle','Source')}: ${esc(METHOD_SOURCES[n][0])}</span></a>`;
 const sections=[
 ['goal',c('Was du hier lernst','What you learn'),c('Du übst Vogelnamen und Quick Find Codes. Hinterlegte Namensvarianten zählen ebenfalls als richtig. Fotos helfen dir, Namen und Vogel zu verbinden; das Bestimmen unbekannter Vogelbilder übst du hier nicht.','Practise bird names and Quick Find Codes. Listed name variants also count as correct. Photos help you connect a name with a bird; identifying unfamiliar bird photos is outside the scope of these exercises.')],
 ['daily',c('Deine Tagesrunde','Your daily round'),c(`Eine Runde beginnt mit fälligen Wiederholungen. Danach kommen neue Namen oder Codes hinzu: insgesamt bis zu ${RULES.round} Fragen pro Runde und ${RULES.newPerDay} neue Lernziele pro Tag, über alle Sprachen und Methoden hinweg. Ein Lernziel ist zum Beispiel der englische Name der Amsel, gefragt auf Deutsch. Neue Namenspaare lernst du kurz kennen, bevor du sie übst.`,`Each round starts with due reviews, followed by new names or codes: up to ${RULES.round} questions per round and ${RULES.newPerDay} new targets per day across all languages and methods. One target might be the English name of the Common Blackbird, prompted in German. New name pairs are introduced briefly before you practise them.`)+`</p><p>`+c('Deine Artenauswahl bestimmt, welche Namen und Codes neu hinzukommen. Bereits gelernte Namen und Codes werden zum geplanten Zeitpunkt wiederholt – unabhängig von deiner aktuellen Artenauswahl. Unter „Weitere Runde selbst zusammenstellen“ legst du die Fragenzahl fest und kannst zum Beispiel zuletzt falsch beantwortete Fragen auswählen. Hier kannst du auch mehr Neues lernen.','Your species selection determines which names and codes are introduced. Previously learned names and codes are reviewed when scheduled, regardless of your current species selection. Under “Build another round yourself”, choose the number of questions and, for example, questions you last answered incorrectly. You can also learn more new material there.')],
 ['formats',c('So kannst du antworten','Ways to answer'),c('Bei „Erst überlegen“ versuchst du zunächst, dich an den Namen zu erinnern. Dann blendest du die Auswahl ein, sobald du möchtest. Bei direkter Auswahl siehst du die Antworten sofort. Beide Methoden üben das Wiedererkennen. Mit Texteingabe übst du, den Namen selbst abzurufen; bei Karteikarten schätzt du deine Antwort selbst ein. „Weiß ich nicht“ zeigt dir die Lösung.','With “Think first”, try to remember the name before revealing the options whenever you are ready. Direct choice shows the options immediately. Both methods practise recognition. Typing practises recalling the name yourself; with flashcards, you assess your own answer. “I don’t know” reveals the solution.')+ref(4)+ref(5)],
 ['feedback',c('Aus Fehlern lernen','Learning from mistakes'),c(`Nach jeder Antwort siehst du die Lösung. Nach einem Fehler oder einer richtigen Antwort mit Hinweis bekommst du bis zu ${RULES.maxRetries} Zusatzversuche, möglichst nach drei anderen Fragen. Ist kein Abstand möglich, entfällt der Zusatzversuch. Diese Versuche helfen beim Einprägen, zählen aber noch nicht als längerfristig sicheres Wissen. Hinweise lassen bisherige Bestätigungen bestehen, fügen aber keine hinzu.`,`You see the solution after every answer. A mistake or a correct answer with a hint can lead to up to ${RULES.maxRetries} extra attempts, preferably after three other questions. If no gap is possible, there is no extra attempt. These attempts help you learn but do not yet count towards lasting retention. Hints keep your existing confirmations but add no new ones.`)+ref(3)],
 ['progress',c('Was dein Lernstand bedeutet','What your progress means'),c(`„Fällig“ heißt: Es ist Zeit für eine Wiederholung. Für einen sicheren Lernstand brauchst du ${RULES.confirmations} richtige, fällige Wiederholungen in Folge, ohne Hinweis und jeweils mindestens ${RULES.minGap/3600000} Stunden nach dem letzten bewerteten Versuch. Je nach Antwortmethode heißt das „Sicher wiedererkannt“, „Sicher abgerufen“ oder bei Karteikarten „Nach eigener Einschätzung sicher“. Dein Lernstand wird für jede Ausgangssprache, jeden gesuchten Namen oder Code und jede Methodenfamilie getrennt erfasst.`,`“Due” means it is time for a review. A secure status requires ${RULES.confirmations} correct due reviews in a row, without hints and each at least ${RULES.minGap/3600000} hours after the last graded attempt. Depending on your answer method, this is called “Securely recognised”, “Securely recalled” or, for flashcards, “Secure by self-assessment”. Progress is tracked separately for each question language, target name or code, and method family.`)+ref(1)+ref(2)+`</p><p>`+c(`Nach der ersten erfolgreichen Übung wiederholst du am nächsten Tag. Danach wachsen die Abstände: ${RULES.intervals.join(', ')} Tage, bis höchstens 60 Tage. Nach einem Fehler beginnt die Bestätigungsserie von vorn; der Abstand wird eine Stufe kürzer und die nächste Wiederholung ist nach zehn Minuten fällig. Nach einer richtigen Antwort mit Hinweis wiederholst du spätestens am Folgetag. Ein schon früher fälliger Termin bleibt bestehen.`,`After your first successful practice, you review the next day. Gaps then grow to ${RULES.intervals.join(', ')} days, up to 60 days. A mistake restarts your confirmation sequence, shortens the gap by one stage and makes the next review due in ten minutes. After a correct answer with a hint, you review by the next day. An earlier due date stays in place.`)+`</p><p>`+c('Du kannst jederzeit früher üben, ohne den nächsten Termin zu verschieben. Auch freies Üben zählt für deinen Lernstand, wenn die Wiederholung fällig ist und genug Zeit vergangen ist. Frühere Lernwerte bleiben erhalten; ehemals „beherrschte“ Ziele werden mit weiteren Wiederholungen bestätigt. Wenn du die Methode wechselst, wird zum Beispiel sicheres Wiedererkennen nicht automatisch als sicherer freier Abruf gewertet.','You can practise early without moving your next review date. Free practice also counts towards your progress when a review is due and enough time has passed. Earlier progress is preserved; previously “mastered” targets are confirmed through further reviews. When you switch methods, secure recognition, for example, does not automatically count as secure recall.')],
 ['research',c('Warum mit Abstand wiederholen?','Why space out reviews?'),c('Sich selbst an einen Namen zu erinnern, die Lösung zu prüfen und später erneut zu üben, hilft beim Behalten. Das zeigen Studien zu aktivem Abrufen, Rückmeldung und verteiltem Lernen. Darauf baut das Lernen hier auf.','Trying to remember a name, checking the answer and practising again later helps you retain it. Studies on retrieval practice, feedback and spaced learning support these principles. They are the basis for learning here.')+ref(0)+ref(6)+`</p><p>`+c('Wie viele Fragen und welche Abstände am besten passen, ist nicht für alle gleich. Die Rundengröße, Wiederholungsabstände und Kriterien für „sicher“ geben dir einen festen Übungsrhythmus; sie sind kein wissenschaftlich ermitteltes Optimum. Die Studien untersuchen die Lernprinzipien, nicht BirdNames DE selbst. Auch „Erst überlegen“ führt nicht zwangsläufig zu besseren Ergebnissen.','The best number of questions and gaps between reviews varies. Round sizes, review intervals and the criteria for “secure” give you a regular practice routine; they are not a scientifically established optimum. The studies examine the learning principles, not BirdNames DE itself. “Think first” does not necessarily lead to better results either.')]
 ];
 return `<h1>${c('Lernmethode','Learning method')}</h1><div class="panel information-page"><p class="intro">${c('Namen kennenlernen, selbst erinnern, Rückmeldung bekommen und mit Abstand wiederholen.','Learn names, try to remember, get feedback and review after a delay.')}</p><p class="muted">${c('Quellen geprüft am 2. November 2026.','Sources reviewed on 2 November 2026.')}</p>${sections.map(([id,title,body])=>`<section aria-labelledby="method-${id}"><h2 id="method-${id}">${title}</h2><p>${body}</p></section>`).join('')}<section aria-labelledby="method-sources"><h2 id="method-sources">${c('Wissenschaftliche Quellen','Scientific sources')}</h2><ol>${METHOD_SOURCES.map(([authors,title,url,de,en],i)=>`<li id="method-source-${i+1}" tabindex="-1"><a href="${url}" target="_blank" rel="noopener noreferrer">${esc(authors)}: <cite>${esc(title)}</cite> ↗</a><p>${esc(english?en:de)}</p></li>`).join('')}</ol></section><a class="button-link" href="#lernen">${c('Zurück zum Lernen','Back to learning')}</a></div>`;
}
